// ————— Which sections have no lesson left —————
// HAND-MAINTAINED. Not generated by build-vite-app.py.
//
// The Goals quests used to offer "Finish one hiragana set" to a learner with
// every hiragana lesson done (found Oct 12 2026 with the demo save): the chain
// knew which sections were OPEN, never which were FINISHED.
//
// ⚠️ THE TEST IS THE MODULE'S OWN, not a copy of it. Each kana and kanji
// module exports `sectionFinished(progress)`, built on the same predicate its
// lesson list ticks with — `placed` lessons from the review quizzes
// (lib/placement.js) included. A second copy here would drift the first time a
// lesson's finishing rule changed, and the kana rule has changed three times.
// The price is loading that module's chunk, which is the chunk the learner
// opens to study anyway; and nothing is loaded for a section with no progress.
//
// Only the sections whose quest is "finish a set" are asked. Grammar's quest
// is the review challenge, which is never finished; the vocabulary bank is
// not going to run out.

import { storage } from "./storage.js";

const SOURCES = {
  hiragana: { key: "tsumiki-hiragana-progress-v2", load: () => import("../modules/Hiragana.jsx") },
  katakana: { key: "tsumiki-katakana-progress-v1", load: () => import("../modules/Katakana.jsx") },
  kanji:    { key: "tsumiki-kanji-progress-v1",    load: () => import("../modules/Kanji.jsx") },
};

/** Is every lesson in this section finished? False for anything unknown or unreadable. */
export async function sectionFinished(id) {
  const src = SOURCES[id];
  if (!src) return false;
  try {
    const r = await storage.get(src.key);
    const p = r ? JSON.parse(r.value) : null;
    if (!p || typeof p !== "object" || !Object.keys(p).length) return false;
    const mod = await src.load();
    return Boolean(mod.sectionFinished && mod.sectionFinished(p));
  } catch (e) { return false; }
}

/** { hiragana, katakana, kanji } → finished? — the engagement module's `finished` prop. */
export async function readFinished() {
  const ids = Object.keys(SOURCES);
  const vals = await Promise.all(ids.map(sectionFinished));
  return Object.fromEntries(ids.map((id, i) => [id, vals[i]]));
}
